import{_ as o,o as i,c as a,a2 as n}from"./chunks/framework.BN2sqjC1.js";const g=JSON.parse(`{"title":"ADR-0063 — Nomi dei file senza estensione per ciò che si apre in una scheda, e rinomina che conserva l'estensione (M22)","description":"","frontmatter":{},"headers":[],"relativePath":"adr/0063-nomi-file-senza-estensione.md","filePath":"adr/0063-nomi-file-senza-estensione.md"}`),t={name:"adr/0063-nomi-file-senza-estensione.md"};function s(c,e,l,r,d,p){return i(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="adr-0063-—-nomi-dei-file-senza-estensione-per-cio-che-si-apre-in-una-scheda-e-rinomina-che-conserva-l-estensione-m22" tabindex="-1">ADR-0063 — Nomi dei file senza estensione per ciò che si apre in una scheda, e rinomina che conserva l&#39;estensione (M22) <a class="header-anchor" href="#adr-0063-—-nomi-dei-file-senza-estensione-per-cio-che-si-apre-in-una-scheda-e-rinomina-che-conserva-l-estensione-m22" aria-label="Permalink to &quot;ADR-0063 — Nomi dei file senza estensione per ciò che si apre in una scheda, e rinomina che conserva l&#39;estensione (M22)&quot;">​</a></h1><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><strong>Stato</strong></td><td>accettata (2026-11-20, decisione dell&#39;owner); recepita in <code>Specifications.md</code> v1.8 (2026-11-20); implementata e rilasciata con la 1.7.3. Integra <a href="./0047-apertura-file-per-tipo-e-presentazioni-marp.html">ADR-0047</a> (il predicato «si apre in una scheda») e generalizza la decisione 5 di <a href="./0060-web-viewer-acceso-di-default.html">ADR-0060</a> (nomi senza <code>.webapp</code>)</td></tr><tr><td><strong>Recepito in</strong></td><td><code>Specifications.md</code> v1.8 (2026-11-20): §2.2.1 (riga «Web viewer» e, nella parte facoltativa, riga «Creare note, rinominare…») e Appendice C.4; <a href="./../spec-v1.8-proposta.html"><code>spec-v1.8-proposta.md</code></a> §4 resta come storia</td></tr><tr><td><strong>Data</strong></td><td>2026-11-19</td></tr><tr><td><strong>Riferimenti spec</strong></td><td>§2.2.1 (riga «Web viewer», <code>Specifications.md:372</code>, che dice «nome senza <code>.webapp</code>»); l&#39;apertura dei file per tipo (ADR-0047) non ha una riga nello spec v1.7; ADR-0037 e ADR-0045</td></tr><tr><td><strong>Devia dallo spec?</strong></td><td><strong>no</strong> (nessun comportamento dello spec contraddice questo ADR). <strong>Recepito nello spec v1.8</strong> (2026-11-20; <a href="./../spec-v1.8-proposta.html"><code>spec-v1.8-proposta.md</code></a> §4): la riga «Web viewer» di §2.2.1 (<code>:372</code>), dove il nome senza <code>.webapp</code> diventa un caso della regola generale, e, facoltativa, una frase nella riga «Creare note, rinominare…» (<code>:336</code>)</td></tr><tr><td><strong>Superfici</strong></td><td>desktop e workbench web: lo stesso codice (<code>packages/workbench</code>), stesse prove vitest; e2e sul mock dei binding e sul core WASM · console e cloud: non applicabile · <strong>nessuna modifica Go</strong>, nessuna modifica di API, database o sync. Registro di parità: nessuna voce nuova</td></tr></tbody></table><h2 id="contesto" tabindex="-1">Contesto <a class="header-anchor" href="#contesto" aria-label="Permalink to &quot;Contesto&quot;">​</a></h2><p>Richiesta dell&#39;owner del 2026-11-19: le estensioni dei file che l&#39;app sa aprire non vanno mostrate; vanno mostrate solo per i file che si aprono fuori dall&#39;app; la rinomina non deve mostrare né far cambiare l&#39;estensione.</p><p>Oggi (albero al commit <code>db1b9d6a</code>):</p><ul><li>L&#39;esploratore toglie solo <code>.md</code> e <code>.webapp</code> (<code>packages/workbench/src/sidebar/FileExplorer.tsx</code>, <code>display</code>, riga 103), le schede solo gli stessi due (<code>workspace/TabBar.tsx</code>, <code>label</code>, righe 17-18). Un disegno compare come <code>Piano.excalidraw</code>, una lavagna come <code>Piano.canvas</code>, una presentazione come <code>Review.marp</code>.</li><li>Una trentina di punti (intestazioni delle viste, pannelli dei collegamenti, embed, anteprime, selettori) hanno ognuno la propria espressione regolare.</li><li>La rinomina preriempie il prompt con il nome intero, estensione compresa (<code>FileExplorer.tsx</code>, <code>rename</code>, riga 195; comando <code>note:rename</code>, <code>commands/registry.ts</code>, <code>renameActive</code>, riga 145), e usa quello che l&#39;utente scrive. Il comando aggiunge <code>.md</code> solo a una nota; per un <code>.excalidraw</code> o un <code>.canvas</code> chi dimentica l&#39;estensione cambia il tipo del file e lo rende illeggibile all&#39;app.</li></ul><p>Il predicato di ADR-0047 esiste già: <code>openTarget(path)</code> (<code>packages/workbench/src/embeds/media.ts:90</code>) risponde <code>&#39;in-app&#39;</code> per note, <code>.marp</code>, disegni, lavagne, basi, applicazioni, immagini, PDF, audio e video, e <code>&#39;external&#39;</code> per ogni altro file, compresi quelli senza estensione (<code>LICENSE</code>, <code>.gitignore</code>).</p><h2 id="decisione" tabindex="-1">Decisione <a class="header-anchor" href="#decisione" aria-label="Permalink to &quot;Decisione&quot;">​</a></h2><ol><li><strong>«Supportato» è <code>openTarget(path) === &#39;in-app&#39;</code>.</strong> L&#39;estensione si nasconde per quei file; per quelli che si aprono fuori dall&#39;app (<code>.docx</code>, <code>.zip</code>, <code>LICENSE</code>, <code>.gitignore</code>) il nome si mostra intero, estensione compresa. Le cartelle non passano di qui: il nome intero.</li><li><strong>Un solo helper</strong>, in <code>packages/workbench/src/embeds/media.ts</code>, accanto a <code>classify</code> e <code>openTarget</code>: <ul><li><code>splitName(name): { stem, ext }</code>: <code>ext</code> è l&#39;estensione conservata, con il punto e con il caso originale, solo se <code>openTarget(name) === &#39;in-app&#39;</code>; altrimenti <code>stem</code> è il nome intero e <code>ext</code> è vuoto. <code>a.b.canvas</code> → <code>a.b</code> e <code>.canvas</code>; <code>Foo.MD</code> → <code>Foo</code> e <code>.MD</code>.</li><li><strong>Caso legacy:</strong> <code>X.excalidraw.md</code> (i disegni del plugin Excalidraw di Obsidian, che sono note) → <code>stem = &#39;X&#39;</code>, <code>ext = &#39;.excalidraw.md&#39;</code>.</li><li><code>displayName(pathOrName): string</code>: <code>splitName</code> sul nome base, restituisce <code>stem</code>.</li><li><code>pickItems(paths): { value, label }[]</code>: gli elementi di un selettore di file (<code>dialog.pick</code>) con l&#39;etichetta di <code>displayPath</code>. Nei selettori che <strong>mescolano tipi</strong> (lavagna: aggiungere nota o media; disegno: immagini, disegni e note incorporati) due file possono avere la stessa etichetta senza estensione (<code>Piano.pdf</code>, <code>Piano.png</code>, <code>Piano.marp</code>): se due etichette coincidono, <strong>senza badare alle maiuscole</strong>, tutte le voci in conflitto mostrano il <strong>percorso completo con l&#39;estensione</strong> (un selettore non ha icone per distinguerle). Usato da <code>canvas/CanvasView.tsx</code> (<code>canvas.addNote</code>, <code>canvas.addMedia</code>) e <code>drawing/embed/commands.ts</code> (immagini, disegni, note).</li><li><code>displayPath(path): string</code>: il percorso come lo mostra l&#39;interfaccia, con le cartelle com&#39;è e il nome del file senza l&#39;estensione nascosta (<code>Cartella/Piano.canvas</code> → <code>Cartella/Piano</code>). Serve dove un nome è mostrato <strong>con la cartella</strong>: intestazioni delle viste (note, disegni, lavagne), titoli di recupero e cronologia, conferma del cestino, elenchi dei selettori <code>dialog.pick</code>, pannello dei collegamenti inversi (la riga di una nota), avvisi degli embed non apribili. Dove basta il nome (schede, esploratore, pannelli) si usa <code>displayName</code>.</li><li><code>nameOf</code> di <code>webapp/model.ts</code> resta esportato per compatibilità interna, ma è scritto sull&#39;helper.</li></ul></li><li><strong>Dove si applica:</strong> esploratore (riga e ordinamento), schede, titoli di grafo, intestazioni delle viste (note, disegni, lavagne, basi, applicazioni), pannelli di collegamenti inversi, collegamenti e segnalibri, embed e anteprime, esportazione, recupero, cronologia e conflitti, selettori di file (<code>dialog.pick</code>, compreso quello delle immagini dei disegni, che prima mostrava l&#39;estensione) e conferma del cestino (il percorso senza estensione per i file, intero per le cartelle). Le regole locali con <code>.replace(/\\.md$/, &#39;&#39;)</code> e simili si sostituiscono con l&#39;helper. Il pannello dei collegamenti oggi toglie l&#39;estensione anche ai file non supportati: va corretto (il nome intero).</li><li><strong>Ordinamento dell&#39;esploratore</strong> sul nome visualizzato, con l&#39;estensione come spareggio: una nota <code>Piano</code> e una lavagna <code>Piano</code> restano vicine e l&#39;ordine è stabile; l&#39;icona li distingue e il tooltip mostra il percorso.</li><li><strong>Rinomina, un solo percorso.</strong> Una funzione <code>promptRename(entry)</code> in <code>packages/workbench/src/app/actions.ts</code>, usata dall&#39;esploratore (menu e F2) e dal comando <code>note:rename</code>; il calcolo del percorso nuovo è la funzione pura <code>renameTarget(path, isDir, input)</code> (stesso file), che si prova da sola: <ul><li>il prompt è preriempito con <code>stem</code>; il percorso nuovo è <code>cartella + stem&#39; + ext</code>, con <code>ext</code> quella <strong>originale</strong> del file;</li><li>se ciò che l&#39;utente scrive termina già con la stessa estensione (senza badare alle maiuscole), non la si raddoppia: <code>Foo.excalidraw</code> per un disegno resta <code>Foo.excalidraw</code>, non <code>Foo.excalidraw.excalidraw</code> (tollera l&#39;abitudine di chi la digita e le prove e2e esistenti);</li><li><strong>un&#39;altra estensione digitata resta parte del nome:</strong> <code>Foo.txt</code> su una nota diventa <code>Foo.txt.md</code>. L&#39;estensione non si cambia dalla rinomina, come richiesto;</li><li><strong>il nome digitato è sempre rifilato</strong> (spazi ai lati tolti), anche per i file non supportati e le cartelle; nome vuoto o di soli spazi, o nome uguale all&#39;attuale: nessuna azione;</li><li>file non supportati e cartelle: il prompt mostra il nome intero, come oggi;</li><li>tutto il resto passa da <code>renameEntry</code> (<code>app/actions.ts</code>): aggiornamento dei collegamenti, conferme, segnalibri. Il trascinamento di un file in un&#39;altra cartella non cambia il nome e non passa di qui.</li></ul></li><li><strong>Invariati.</strong> Il <strong>testo che i collegamenti inseriscono</strong> (<code>editor/completionEngine.ts</code>, <code>linkTextFor</code>): un <code>.marp</code> resta <code>Review.marp</code> perché i collegamenti si risolvono per estensione nel core Go; i <strong>percorsi</strong> nei tooltip; il <strong>selettore rapido</strong> e la <strong>ricerca</strong>, che mostrano già il titolo senza estensione dall&#39;indice Go.</li><li><strong>Nessuna modifica Go né di protocollo.</strong> Il binding di rinomina non controlla le estensioni; il nome sul disco, sulla sync e nel cloud è quello di sempre.</li><li><strong>Parità</strong> (ADR-0037, ADR-0045): lo stesso codice condiviso per desktop e workbench, quindi nessuna voce nuova nel registro; si aggiorna la nota della voce dell&#39;esploratore in <code>shared/parity/features.yaml</code>. Prove: vitest per <code>splitName</code>, <code>displayName</code> e <code>promptRename</code> (casi <code>.md</code>, <code>.MD</code>, <code>.excalidraw.md</code>, <code>.png</code>, <code>.docx</code>, <code>LICENSE</code>, <code>.gitignore</code>, <code>a.b.canvas</code>), aggiornamento dei test che oggi aspettano l&#39;estensione, e2e sul mock dei binding e sul core WASM, con un caso nuovo: rinominare un disegno da F2 conserva <code>.excalidraw</code>.</li></ol><h2 id="alternative-considerate" tabindex="-1">Alternative considerate <a class="header-anchor" href="#alternative-considerate" aria-label="Permalink to &quot;Alternative considerate&quot;">​</a></h2><ul><li><strong>Togliere solo <code>.md</code> e <code>.webapp</code> (lo stato attuale), aggiungendo caso per caso</strong> — scartata: è la causa delle trenta regole locali, e ogni tipo nuovo ripete il difetto.</li><li><strong>Un elenco di estensioni nascoste separato da <code>openTarget</code></strong> — scartata: due elenchi si disallineano; «supportato» è per definizione ciò che si apre in una scheda (ADR-0047).</li><li><strong>Mostrare l&#39;estensione nella rinomina e lasciarla modificabile</strong> — scartata dall&#39;owner: è il difetto segnalato (si perde il tipo del file).</li><li><strong>Rendere l&#39;estensione una parte non modificabile del campo</strong> — scartata: un campo composto complica la tastiera e i lettori di schermo; il prompt senza estensione e la sua ricollocazione danno lo stesso risultato.</li><li><strong>Cambiare anche il testo inserito dai collegamenti</strong> — scartata: i collegamenti si risolvono per estensione (<code>Review.marp</code>), e una forma senza estensione ne cambierebbe il significato.</li><li><strong>Una regola dentro il core Go (titolo dell&#39;indice)</strong> — non necessaria: il core già dà il titolo senza estensione; la regola serve solo all&#39;interfaccia.</li></ul><h2 id="conseguenze" tabindex="-1">Conseguenze <a class="header-anchor" href="#conseguenze" aria-label="Permalink to &quot;Conseguenze&quot;">​</a></h2><ul><li>Ciò che si apre nell&#39;app si legge ovunque senza estensione; due file con lo stesso nome e tipi diversi (<code>Piano</code> nota e <code>Piano</code> lavagna) sono distinguibili solo dall&#39;icona e dal tooltip: è il costo accettato.</li><li>Rinominare non può più cambiare il tipo di un file supportato; per farlo servono il file system o un altro comando. Chi vuole davvero un&#39;altra estensione non ha un modo dall&#39;app: limite dichiarato.</li><li>Per i file non supportati nulla cambia.</li><li>Un utente abituato a digitare l&#39;estensione continua a funzionare (non si raddoppia).</li><li>Da verificare a mano, con il runbook <a href="./../qa/m22-nomi-file-e-applicazioni.html"><code>docs/qa/m22-nomi-file-e-applicazioni.md</code></a>: l&#39;esploratore su un vault reale (<code>Desktop_UI</code>, <code>SlideClarae</code>, <code>SATAP</code> senza estensione) e la rinomina con F2 su un disegno, un canvas, una presentazione e un file non supportato.</li></ul>',13)])])}const u=o(t,[["render",s]]);export{g as __pageData,u as default};
